# This is a Python script that simulates a simple security system with a vault and a password.

class Vault:
    def __init__(self):
        self.password = "FLOAFLOSH"
        self.is_locked = True

    def check_password(self, attempt):
        if attempt == self.password:
            self.is_locked = False
            return "Access granted. The vault is now unlocked."
        else:
            return "Access denied. Incorrect password."

    def is_open(self):
        return not self.is_locked

# Simulate a simple interaction
def main():
    vault = Vault()
    print("Welcome to the vault. Please enter the password to gain access.")
    attempt = input("Enter password: ")
    result = vault.check_password(attempt)
    print(result)
    if not vault.is_open():
        print("The vault remains locked.")
    else:
        print("The vault is unlocked. You may proceed.")

if __name__ == "__main__":
    main()
